type ViewState = { kind: 'chart'; zoom: number } | { kind: 'table'; sort: SortKey };
class ViewHandler {
  private views = new Map<ViewId, ViewState>();
  open(view: ViewState): ViewId { const id = crypto.randomUUID(); this.views.set(id, view); return id; }
  close(id: ViewId): void { this.views.delete(id); }      // unregister, then drop the state
  sync(model: Model): void { for (const [id, v] of this.views) this.render(id, v, model); }
  private render(id: ViewId, view: ViewState, m: Model): void {
    switch (view.kind) {                                   // exhaustive by the union
      case 'chart': return drawChart(id, view, m);
      case 'table': return drawTable(id, view, m);
    }
  }
}
